    def self.damage_lines(values,locale=language,detail=false)
      return [] unless values
      values.inject([]) do |rows,(unit,step,hidden,first)|
        prefix=values.size>1 || unit.actor? ? unit.name+': ' : ''
        if hidden;rows<<prefix+t('Forecast locked.','Forecast locked.',locale);next rows;end
        result=step && !step[:reason] ? step : first
        if result
          matching=result[:rows].select { |r| r[:target_index]==(unit.actor? ? :self : unit.index) }
          matching.each do |r|
            healing=r[:mean]<0
            amount=healing ? -r[:mean] : r[:mean]
            low,high=healing ? [-r[:max],-r[:min]] : [r[:min],r[:max]]
            text=prefix+(first ? t('Current first hit: ','Current first hit: ',locale) : '')+(healing ? t('Recovery ','Recovery ',locale) : '')+'≈ '+amount.round.to_s+' '+r[:resource]
            text+=' ('+low.round.to_s+'–'+high.round.to_s+')' if detail && low!=high
            text+=t(' · direct damage',' · direct damage',locale) if result[:direct_only] && !first
            rows<<text
          end
          rows<<prefix+t('Continuation unverified.','Continuation unverified.',locale) if detail && (first || result[:followup_unknown])
        else
          rows<<prefix+t('Forecast unavailable.','Forecast unavailable.',locale)
        end
        rows<<t('Reason: ','Reason: ',locale)+step[:reason].to_s if detail && step && step[:reason]
        rows
      end
    end
    def self.preview(scene,object,user,source=nil,target=nil,weapon=nil,selected=false,immediate=false)
      return description(object,user).dup unless user && $game_party.in_battle
      resolved=object
      if object.is_a?(RPG::Weapon)
        source=weapon=object;@attack_ids ||= {};key=[live_key(user),object.id]
        unless @attack_ids.has_key?(key)
          @attack_ids.shift while @attack_ids.size>=64
          @attack_ids[key]=BS2Suite::Projection.weapon(user,object).attack_skill_id
        end
        resolved=$data_skills[@attack_ids[key]]
      end
      return description(object,user).dup unless resolved.is_a?(RPG::UsableItem)
      values=results(resolved,user,source,target,weapon,selected,immediate)
      step=values && values.map { |_,s,h,_| h ? nil : s }.compact[0]
      actual=step && step[:item] || resolved
      rows=formula_lines(actual,step)+damage_lines(values)
      count=step && step[:hit_count];rows<<t('Hits: ','Hits: ')+count.to_s if count && count>1
      rows+description(object.is_a?(RPG::Weapon) ? object : actual,user)
    end
