      enemy=scene.instance_variable_get(:@enemy_window);ally=scene.instance_variable_get(:@actor_window)
      window=[enemy,ally].find { |w| w && w.active && w.visible && w.open? }
      target=window && (window.equal?(enemy) ? $game_troop.alive_members[enemy.index] : $game_party.battle_members[ally.index]);selected=!!window
      window ||= [scene.instance_variable_get(:@skill_window),scene.instance_variable_get(:@item_window)].find { |w| w && w.active && w.visible && w.open? }
      object=selected ? user.input && user.input.item : window && window.item
      return bs2099993_old_battle(scene) unless BS2Suite::CatalogUI.supported?(object)
      lines=BS2Suite::CatalogUI.preview(scene,object,user,nil,target,nil,selected)
      [row('T',object.name)]+catalog_rows(object,lines,capacity-3)+[row('D','F7 — details')]
    end
    alias bs2099993_old_menu menu_rows
    def menu_rows(scene)
      window=selected_window(scene);object=window && defined?(BS2QoL::Reference) && BS2QoL::Reference.object_for(window)
      return bs2099993_old_menu(scene) unless BS2Suite::CatalogUI.supported?(object)
      rows=[row('T',object.name)];lines=BS2Suite::CatalogUI.description(object,actor_for(scene)).dup
      if object.is_a?(RPG::EquipItem)
        view=equip_projection(actor_for(scene),object,scene)
        lines+=comparison(actor_for(scene),view) if view
      end
      rows+catalog_rows(object,lines,capacity-3)+[row('D','F7 — details')]
    end
  end
end
end
if defined?(BS2QoL::PracticalCard)
