class BS2QoL::PracticalCard
  alias bs2099993_initialize initialize
  def initialize(object,actor=nil,locale=:en)
    if object.is_a?(RPG::State)
      @object=@resolved=object;@actor=actor;@language=locale;@sections=[];@section_names=[]
      lines=BS2Suite::CatalogUI.description(object,actor,false,locale)
      add(t('State','State'),lines.empty? ? [t('No additional properties.','No additional properties.')] : lines)
      return
    end
    bs2099993_initialize(object,actor,locale)
    unless BS2Suite::CatalogUI.supported?(object)
      @sections=@sections.map { |rows| rows.map { |line| BS2Suite::CatalogUI.tidy(line,locale) }.compact.uniq }
      return
    end
    # Retain existing source resolution and cost arithmetic, then rebuild the
    # presentation from the focused mechanics rather than layering old prose.
    costs=object.is_a?(RPG::UsableItem) ? practical_cost.map { |line| BS2Suite::CatalogUI.tidy(line,locale) }.compact : []
    @sections=[];@section_names=[]
    base=BS2Suite::CatalogUI.description(@resolved,@actor,false,locale).dup
    if @resolved.is_a?(RPG::UsableItem) && @resolved.for_opponent?
      info=[]
      info<<t('Physical hit','Physical hit') if @resolved.hit_type==1
      info<<t('Magical hit','Magical hit') if @resolved.hit_type==2
      if !@resolved.damage.none? && @resolved.damage.formula.to_s !~ /\A\s*(?:0|10)\s*\z/
        info<<element(@resolved.damage.element_id) if @resolved.damage.element_id>1
        info<<t('no critical','no critical') unless @resolved.damage.critical
      end
      base<<info.join(' · ') unless info.empty?
    end
    if defined?(BS2Suite::AutoStealth) && object.is_a?(RPG::Skill) && object.id==BS2Suite::AutoStealth::SKILL
      base<<BS2Suite::Keys.token(:Z)+t(' — automatic stealth',' — automatic stealth')
    end
    add(object.is_a?(RPG::EquipItem) ? t('Equipment','Equipment') : t('Use','Use'),base+costs)
    if object.is_a?(RPG::UsableItem)
      effects=BS2Suite::CatalogUI.resource_lines(@resolved,locale)
      effects<<BS2Suite::CatalogUI.color('TP','a')+' +'+@resolved.tp_gain.to_s+' × '+BS2Suite::CatalogUI.color('TCR','a') if @resolved.tp_gain!=0
      @resolved.effects.select { |e| e.code==21 && e.data_id>0 }.each do |effect|
        state=$data_states[effect.data_id];next unless state
        properties=BS2Suite::CatalogUI.description(state,nil,false,locale)
        unless properties.empty?
          row=BS2Suite::CatalogV1.entry(state)
          effects<<((row && row['names'][locale.to_s]) || state.name)+':'
          effects+=properties
        end
      end
      if defined?(BS2Suite::Books) && @actor
        BS2Suite::Books.skills(object).each do |skill|
          row=BS2Suite::CatalogV1.entry(skill)
          effects<<(@actor.skill_learn?(skill) ? '✓ ' : '○ ')+((row && row['names'][locale.to_s]) || skill.name)
        end
      end
      add(t('Effects','Effects'),effects.uniq)
      forecast=compact_forecast
      if forecast.empty?;add(t('Formula','Formula'),practical_formula)
      else;add(t('Targets','Targets'),forecast);end
    elsif object.is_a?(RPG::Weapon)
      if @actor && $game_party.in_battle && defined?(BS2Suite::ForecastContext)
        add(t('Attack','Attack'),BS2Suite::CatalogUI.preview(SceneManager.scene,object,@forecast09991_actor || @actor,object,nil,object,false,true))
      else;add(t('Attack','Attack'),BS2Suite::CatalogUI.formula_lines(object,nil,locale));end
    end
    add(t('Details','Details'),[t('No additional properties.','No additional properties.')]) if @sections.empty?
  end
  alias bs2099993_title title
  def title
    return bs2099993_title unless @object.is_a?(RPG::State)
    row=BS2Suite::CatalogV1.entry(@object);row ? row['names'][language.to_s] : @object.name
  end
  def forecast09991_steps
    return [] unless forecast09991_context?
    values=BS2Suite::CatalogUI.results(@object,@forecast09991_actor,nil,nil,nil,@forecast09991_selected,true)
    (values || []).map { |row| row[0,3] }
  end
  def compact_forecast
    user=instance_variable_get(:@forecast09991_actor) || actor
    return [] unless user && $game_party.in_battle && defined?(BS2Suite::ForecastContext)
    selected=!!instance_variable_get(:@forecast09991_selected)
    values=BS2Suite::CatalogUI.results(@object,user,nil,nil,nil,selected,true)
    step=values && values.map { |_,s,h,_| h ? nil : s }.compact[0]
    rows=BS2Suite::CatalogUI.formula_lines(step && step[:item] || @resolved,step,language)
    rows+=BS2Suite::CatalogUI.damage_lines(values,language,true)
    count=step && step[:hit_count];rows<<t('Hits: ','Hits: ')+count.to_s if count && count>1
    rows
  end
  alias bs2099993_effects practical_effects
  def practical_effects
    rows=bs2099993_effects.reject { |line| line =~ /\A(?:Восстановление (?:HP|MP):|Потери (?:HP|MP):|(?:HP|MP) (?:recovery|loss):)/ }
    BS2Suite::CatalogUI.resource_lines(@resolved,language)+rows
  end
  def practical_formula;BS2Suite::CatalogUI.formula_lines(@resolved,nil,language);end
end
class Window_BS2QReference
